"""Mutants of the verification engine (lib/analyzer, lib/parse, lib/haltsql, lib/pgquery).

Each entry is (name, file, snippet, replacement): one security regression a careless
change could introduce. Every mutant must be KILLED by the test suite, except the ones
in EQUIVALENT, which change nothing observable (the reason is given).
"""

TESTS = "test/analyzer test/parse test/golden test/property test/runner test/conformance test/corpus test/cli test/pgquery test/fuzz"

EQUIVALENT = {'parse: depth/node limits off': 'this is only the early stop of the tree walk; the limits are '
                                 'compared again by the caller',
 'rules: LIMIT ALL accepted': "the parser already maps LIMIT ALL to 'no limit', which the next "
                              'branch rejects',
 'rules: LIMIT NULL accepted': "same as LIMIT ALL: the parser folds LIMIT NULL into 'no limit'"}

